// ── NousBoy games console ────────────────────────────────────────────────────

function GamesConsole({ ctx }) {
  const [activeId, setActiveId] = React.useState('g1')
  const [on, setOn] = React.useState(false)
  const [consoleMode, setConsoleMode] = React.useState('nousboy')   // 'nousboy' | 'snes'
  const game = GAMES.find(g => g.id === activeId) || GAMES[0]
  const asset = useHtmlAsset(ctx, on && game.file ? `/asset/game/${game.file}` : null)

  // NES/SNES emulator state
  const [romType, setRomType] = React.useState(null)   // 'nes' | 'snes' | null
  const [romFile, setRomFile] = React.useState(null)   // File object from picker
  const [emulatorUrl, setEmulatorUrl] = React.useState(null)

  // When switching to a romType game, prepare the emulator
  React.useEffect(() => {
    if (on && game.romType) {
      setRomType(game.romType)
      setEmulatorUrl(null)
      setRomFile(null)
    } else {
      setRomType(null)
      setEmulatorUrl(null)
      setRomFile(null)
    }
  }, [on, game.romType])

  // Build emulator HTML for NES or SNES via EmulatorJS
  function buildEmulatorHtml(core, file) {
    const romUrl = URL.createObjectURL(file)
    const romName = file.name.replace(/\.[^.]+$/, '')
    return `<!doctype html>
<html><head><meta charset="utf-8"><style>
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{width:100%;height:100%;background:#000;overflow:hidden}
  #game{width:100%;height:100%}
</style></head><body>
<div id="game"></div>
<script>
  window.EJS_player = '#game';
  window.EJS_core = '${core}';
  window.EJS_gameUrl = '${romUrl}';
  window.EJS_gameName = '${romName}';
  window.EJS_pathtodata = 'https://cdn.emulatorjs.org/stable/data/';
  window.EJS_startOnLoaded = true;
  window.EJS_fullscreenOnLoaded = false;
  const s = document.createElement('script');
  s.src = 'https://cdn.emulatorjs.org/stable/data/loader.js';
  s.onerror = () => { document.body.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100vh;color:#fca5a5;font-family:system-ui">EmulatorJS runtime unavailable — check network</div>'; };
  document.head.appendChild(s);
</script></body></html>`
  }

  // Dispatch a synthetic key stroke to the active screen so the emulator / ROM
  // (or the page's own handlers) receive it — this is what the on-screen D-pad
  // and A/B buttons drive. Tries the iframe document first, then falls back to
  // the host window (covers the local HTML games + the NES/SNES cores).
  function sendGameKey(key) {
    haptic('tap')
    const target = document.activeElement && document.activeElement.tagName === 'IFRAME'
      ? document.activeElement.contentDocument || document.activeElement
      : document
    const fire = (el) => {
      try {
        el.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true }))
        el.dispatchEvent(new KeyboardEvent('keyup', { key, bubbles: true }))
      } catch { /* cross-origin iframe — ignore */ }
    }
    fire(target)
  }

  // On-screen controller button factory (D-pad + A/B).
  const PadBtn = ({ label, title, onClick, tone, style }) => h('button', {
    type: 'button',
    title,
    onClick,
    className: 'flex items-center justify-center select-none rounded-lg border font-mono font-bold transition-all active:scale-90',
    style: Object.assign({
      width: 44, height: 44, fontSize: '1rem',
      background: 'rgba(255,255,255,0.05)',
      borderColor: 'rgba(255,255,255,0.12)',
      color: 'rgba(255,255,255,0.85)',
      cursor: 'pointer',
      boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.10), 0 2px 6px rgba(0,0,0,0.4)',
    }, style || {}),
  }, label)

  const body = !on
    ? h('div', {
        className: 'absolute inset-0 flex items-center justify-center font-mono',
        style: { background: '#0d1210', fontSize: '0.6rem', letterSpacing: '0.4em', color: 'rgba(158,255,190,0.25)' },
      }, 'press start')
    : game.src
      ? h('iframe', { src: game.src, title: game.name, className: 'absolute inset-0 h-full w-full border-0' })
      : game.romType && romFile
        ? h('iframe', {
            src: emulatorUrl,
            title: game.name,
            className: 'absolute inset-0 h-full w-full border-0',
            sandbox: 'allow-scripts allow-same-origin allow-forms',
          })
        : game.romType && !romFile
          ? h('div', {
              className: 'absolute inset-0 flex flex-col items-center justify-center gap-3 font-mono',
              style: { background: '#0d1210', color: 'rgba(158,255,190,0.5)', fontSize: '0.6rem' },
            }, [
              h('span', { style: { fontSize: '0.7rem', color: 'rgba(158,255,190,0.8)' } }, game.name + ' — select ROM'),
              h('button', {
                type: 'button',
                onClick: () => {
                  const input = document.createElement('input')
                  input.type = 'file'
                  input.accept = romType === 'nes' ? '.nes,.sfc,.swc' : '.sfc,.smc,.fig,.swc,.bsx'
                  input.onchange = () => {
                    const f = input.files && input.files[0]
                    if (!f) return
                    setRomFile(f)
                    const html = buildEmulatorHtml(romType, f)
                    const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }))
                    setEmulatorUrl(url)
                  }
                  input.click()
                },
                className: 'rounded-md border border-(--ui-stroke-secondary) px-3 py-1 text-xs text-(--ui-text-secondary) hover:text-foreground',
              }, 'load ROM'),
            ])
          : asset.loading
            ? h('div', { className: 'absolute inset-0 flex items-center justify-center' }, h(GlyphSpinner, {}))
            : asset.error
              ? h('div', {
                  className: 'absolute inset-0 flex items-center justify-center font-mono',
                  style: { fontSize: '0.6rem', color: '#fca5a5' },
                }, 'cartridge error')
              : h('iframe', { src: asset.url, title: game.name, className: 'absolute inset-0 h-full w-full border-0' })

  // Mode switch: Nous Boy (local HTML games) vs SNES (emulator ROMs).
  if (consoleMode === 'snes') {
    return h('div', { className: 'mx-auto mt-6 w-full', style: { maxWidth: 720 } }, [
      h('div', { key: 'mode', className: 'mb-3 flex items-center justify-center gap-2' }, [
        ModeBtn({ active: consoleMode === 'nousboy', label: 'Nous Boy', onClick: () => setConsoleMode('nousboy') }),
        ModeBtn({ active: consoleMode === 'snes', label: 'SNES', onClick: () => setConsoleMode('snes') }),
      ]),
      h(SnesGame, { key: 'snes' }),
    ])
  }

  return h('div', { className: 'mx-auto mt-6 w-full', style: { maxWidth: 420 } }, [
    h('div', { key: 'mode', className: 'mb-3 flex items-center justify-center gap-2' }, [
      ModeBtn({ active: consoleMode === 'nousboy', label: 'Nous Boy', onClick: () => setConsoleMode('nousboy') }),
      ModeBtn({ active: consoleMode === 'snes', label: 'SNES', onClick: () => setConsoleMode('snes') }),
    ]),
    h('div', {
      key: 'shell',
      className: 'relative',
      style: {
        borderRadius: 24,
        background: 'rgba(14,16,20,0.75)',
        backdropFilter: 'blur(18px) saturate(140%)',
        WebkitBackdropFilter: 'blur(18px) saturate(140%)',
        border: '1px solid rgba(255,255,255,0.08)',
        boxShadow: '0 18px 50px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.10)',
        padding: '16px',
      },
    }, [
      h('div', {
        key: 'hd',
        className: 'mb-3 flex items-center justify-between',
      }, [
        h('span', {
          key: 't',
          className: 'font-mono font-bold uppercase',
          style: { fontSize: '0.6rem', letterSpacing: '0.4em', color: 'rgba(255,255,255,0.6)' },
        }, 'NousBoy'),
        h(RemoteButton, { key: 'p', label: on ? 'on' : 'off', title: 'Power', tone: on ? 'power' : 'off', onClick: () => setOn(v => !v) }),
      ]),
      // screen housing — dark olive bezel
      h('div', {
        key: 'bez',
        className: 'relative',
        style: {
          borderRadius: 14,
          background: '#20261f',
          padding: 14,
          boxShadow: 'inset 0 2px 10px rgba(0,0,0,0.85), inset 0 0 0 1px rgba(255,255,255,0.05)',
        },
      }, h('div', {
        className: 'relative overflow-hidden rounded bg-black',
        style: { aspectRatio: '4 / 3' },
      }, body)),
      // cartridge selector
      h('div', {
        key: 'carts',
        className: 'mt-3 flex flex-wrap items-center justify-center gap-1.5',
      }, GAMES.map(g =>
        h('button', {
          key: g.id,
          type: 'button',
          title: g.name,
          onClick: () => { haptic('tap'); setActiveId(g.id) },
          className: 'flex-shrink-0 select-none rounded-full border px-3 font-mono transition-transform active:scale-95',
          style: {
            height: 30,
            fontSize: '0.6rem',
            background: activeId === g.id ? 'rgba(74,222,128,0.16)' : 'rgba(255,255,255,0.04)',
            borderColor: activeId === g.id ? 'rgba(74,222,128,0.5)' : 'rgba(255,255,255,0.08)',
            color: activeId === g.id ? '#bbf7d0' : 'rgba(255,255,255,0.4)',
          },
        }, g.name),
      )),
      h('div', {
        key: 'pad',
        className: 'mt-3 flex items-center justify-between gap-3',
      }, [
        // D-pad (left cluster)
        h('div', {
          key: 'dpad',
          className: 'relative',
          style: { width: 132, height: 132 },
        }, [
          h(PadBtn, { key: 'u', label: '▲', title: 'Up', onClick: () => sendGameKey('ArrowUp'), style: { position: 'absolute', top: 0, left: 44 } }),
          h(PadBtn, { key: 'l', label: '◀', title: 'Left', onClick: () => sendGameKey('ArrowLeft'), style: { position: 'absolute', top: 44, left: 0 } }),
          h(PadBtn, { key: 'c', label: '', title: 'Center', onClick: () => {}, style: { position: 'absolute', top: 44, left: 44, background: 'rgba(255,255,255,0.02)', borderColor: 'rgba(255,255,255,0.06)', cursor: 'default' } }),
          h(PadBtn, { key: 'r', label: '▶', title: 'Right', onClick: () => sendGameKey('ArrowRight'), style: { position: 'absolute', top: 44, left: 88 } }),
          h(PadBtn, { key: 'd', label: '▼', title: 'Down', onClick: () => sendGameKey('ArrowDown'), style: { position: 'absolute', top: 88, left: 44 } }),
        ]),
        // A / B face buttons (right cluster)
        h('div', {
          key: 'ab',
          className: 'flex items-center gap-3',
        }, [
          h(PadBtn, { key: 'b', label: 'B', title: 'B', onClick: () => sendGameKey('b'), style: { background: 'rgba(248,113,113,0.16)', borderColor: 'rgba(248,113,113,0.45)', color: '#fca5a5' } }),
          h(PadBtn, { key: 'a', label: 'A', title: 'A', onClick: () => sendGameKey('a'), style: { background: 'rgba(74,222,128,0.16)', borderColor: 'rgba(74,222,128,0.45)', color: '#bbf7d0' } }),
        ]),
      ]),
      h('div', {
        key: 'hint',
        className: 'mt-2 text-center font-mono',
        style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)' },
      }, 'click the screen first, then use the pad / A·B or arrows / WASD / space'),
    ]),
  ])
}

// Console mode switcher (Nous Boy <-> SNES) used inside GamesConsole.
const ModeBtn = ({ active, label, onClick }) => h('button', {
  type: 'button',
  onClick: () => { haptic('tap'); onClick() },
  className: 'rounded-full border px-4 py-1 font-mono transition-colors',
  style: {
    fontSize: '0.6rem',
    letterSpacing: '0.12em',
    textTransform: 'uppercase',
    background: active ? 'rgba(56,189,248,0.16)' : 'transparent',
    borderColor: active ? 'rgba(56,189,248,0.5)' : 'rgba(255,255,255,0.12)',
    color: active ? 'var(--ui-text-primary)' : 'var(--ui-text-tertiary)',
    cursor: 'pointer',
  },
}, label)

// ── SNES emulator (ported from the standalone snes-emulator plugin) ───────────
// Roms stay local; the live emulator is "parked" in a hidden iframe so leaving
// the Games tab does not destroy the session. Cross-origin, so the D-pad/A·B
// synthetic keys can't reach it — click the emulator and use physical keys.
let snesParkingLot = null
let snesPlayerFrame = null

function SnesGame({}) {
  const slotRef = React.useRef(null)
  const [romName, setRomName] = React.useState('')

  function ensureFrame() {
    if (snesPlayerFrame) return snesPlayerFrame
    const lot = document.createElement('div')
    lot.style.cssText = 'position:fixed;left:-10000px;top:-10000px;width:1px;height:1px;overflow:hidden;visibility:hidden;pointer-events:none;'
    const frame = document.createElement('iframe')
    frame.title = 'SNES emulator'
    frame.setAttribute('sandbox', 'allow-scripts allow-same-origin')
    frame.className = 'h-full w-full border-0'
    frame.srcdoc = `<!doctype html><html><head><meta charset="utf-8"><style>
      :root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#111827;color:#e5e7eb;font-family:system-ui,sans-serif}
      #setup{min-height:100vh;display:grid;place-items:center;padding:24px}.card{width:min(620px,100%);padding:28px;border:1px solid #374151;border-radius:14px;background:#172033}
      h2{margin:0 0 10px;font-size:22px}p{color:#b7c0d1;line-height:1.5}label{display:block;margin:22px 0 8px;font-size:14px;color:#cbd5e1}
      input{width:100%;padding:12px;border:1px solid #4b5563;border-radius:8px;background:#0f172a;color:#e5e7eb}
      .note{margin-top:18px;font-size:12px;color:#94a3b8}.error{color:#fca5a5;min-height:18px;margin-top:10px}#game{width:100vw;height:100vh}</style></head><body>
      <div id="setup"><main class="card"><h2>Load your SNES ROM</h2><p>Select a legally obtained Super Nintendo ROM from your computer. The emulator stays alive when you leave this tab, so its session continues when you return.</p>
      <label for="rom">.sfc or .smc file</label><input id="rom" type="file" accept=".sfc,.smc,.fig,.swc,.bsx"><div id="error" class="error"></div>
      <p class="note">The ROM stays local to this embedded emulator. It is not uploaded or saved by Hermes.</p></main></div>
      <script>const error=document.getElementById('error');
      function launch(file){const g=document.createElement('div');g.id='game';document.body.replaceChildren(g);
      window.EJS_player='#game';window.EJS_core='snes9x';window.EJS_gameUrl=URL.createObjectURL(file);
      window.EJS_gameName=file.name.replace(/\\.[^.]+$/,'');
      window.EJS_pathtodata='https://cdn.emulatorjs.org/stable/data/';window.EJS_startOnLoaded=true;window.EJS_fullscreenOnLoaded=false;
      const l=document.createElement('script');l.src='https://cdn.emulatorjs.org/stable/data/loader.js';
      l.onerror=()=>{document.body.innerHTML='<div id="setup"><main class="card"><h2>Emulator runtime unavailable</h2><p>EmulatorJS could not load. Check your network connection and try again.</p></main></div>'};
      document.head.appendChild(l);}
      document.getElementById('rom').addEventListener('change',e=>{const f=e.target.files&&e.target.files[0];if(!f)return;
      if(!/\\.(sfc|smc|fig|swc|bsx)$/i.test(f.name)){error.textContent='Choose an SNES ROM with a supported extension (.sfc or .smc recommended).';return;}
      parent.postMessage({type:'hermes-snes-loaded',name:f.name},'*');launch(f);});</script></body></html>`
    lot.appendChild(frame)
    document.body.appendChild(lot)
    snesParkingLot = lot
    snesPlayerFrame = frame
    return frame
  }

  // Forward an on-screen control press into the emulator iframe. The iframe is
  // same-origin (blob/srcdoc), so we can inject a listener that replays the key
  // as a real KeyboardEvent on its own document — that's what makes the D-pad /
  // A·B actually drive SNES (physical keys also still work if you click in).
  function sendKey(key) {
    haptic('tap')
    const frame = snesPlayerFrame
    if (frame && frame.contentWindow) {
      try { frame.contentWindow.postMessage({ type: 'hermes-snes-key', key }, '*') } catch { /* ignore */ }
    }
  }

  React.useEffect(() => {
    const frame = ensureFrame()
    slotRef.current && slotRef.current.appendChild(frame)
    // Inject the key-forwarder into the iframe document (same-origin blob).
    const inject = () => {
      try {
        const doc = frame.contentDocument
        if (doc && !doc.getElementById('hermes-key-fwd')) {
          const s = doc.createElement('script')
          s.id = 'hermes-key-fwd'
          s.textContent = "window.addEventListener('message',function(e){if(e.data&&e.data.type==='hermes-snes-key'){var k=e.data.key;document.dispatchEvent(new KeyboardEvent('keydown',{key:k,bubbles:true}));setTimeout(function(){document.dispatchEvent(new KeyboardEvent('keyup',{key:k,bubbles:true}))},90);}});"
          doc.body.appendChild(s)
        }
      } catch { /* cross-origin before load — ignore */ }
    }
    frame.addEventListener('load', inject)
    inject()
    const receive = (e) => { if (e.data && e.data.type === 'hermes-snes-loaded') setRomName(e.data.name || '') }
    window.addEventListener('message', receive)
    return () => {
      frame.removeEventListener('load', inject)
      window.removeEventListener('message', receive)
      if (snesParkingLot && frame.parentElement !== snesParkingLot) snesParkingLot.appendChild(frame)
    }
  }, [])

  const Pad = ({ label, title, onClick, style }) => h('button', {
    type: 'button', title, onClick,
    className: 'flex items-center justify-center select-none rounded-lg border font-mono font-bold transition-all active:scale-90',
    style: Object.assign({ width: 44, height: 44, fontSize: '1rem', background: 'rgba(255,255,255,0.05)', borderColor: 'rgba(255,255,255,0.12)', color: 'rgba(255,255,255,0.85)', cursor: 'pointer', boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.10), 0 2px 6px rgba(0,0,0,0.4)' }, style || {}),
  }, label)

  return h('div', { className: 'mx-auto mt-6 w-full', style: { maxWidth: 720 } }, [
    h('div', { key: 'hd', className: 'mb-3 flex items-center justify-between' }, [
      h('span', { key: 't', className: 'font-mono font-bold uppercase', style: { fontSize: '0.6rem', letterSpacing: '0.4em', color: 'rgba(255,255,255,0.6)' } }, 'SNES'),
      h('span', { key: 'r', className: 'font-mono', style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)' } }, romName ? 'playing: ' + romName : 'load a .sfc / .smc ROM'),
    ]),
    h('div', { key: 'slot', ref: slotRef, className: 'relative overflow-hidden rounded border border-(--ui-stroke-secondary)', style: { aspectRatio: '4 / 3', background: '#000' } }),
    h('div', { key: 'pad', className: 'mt-3 flex items-center justify-between gap-3' }, [
      h('div', { key: 'dpad', className: 'relative', style: { width: 132, height: 132 } }, [
        h(Pad, { key: 'u', label: '▲', title: 'Up', onClick: () => sendKey('ArrowUp'), style: { position: 'absolute', top: 0, left: 44 } }),
        h(Pad, { key: 'l', label: '◀', title: 'Left', onClick: () => sendKey('ArrowLeft'), style: { position: 'absolute', top: 44, left: 0 } }),
        h(Pad, { key: 'c', label: '', title: 'Center', onClick: () => {}, style: { position: 'absolute', top: 44, left: 44, background: 'rgba(255,255,255,0.02)', borderColor: 'rgba(255,255,255,0.06)', cursor: 'default' } }),
        h(Pad, { key: 'r', label: '▶', title: 'Right', onClick: () => sendKey('ArrowRight'), style: { position: 'absolute', top: 44, left: 88 } }),
        h(Pad, { key: 'd', label: '▼', title: 'Down', onClick: () => sendKey('ArrowDown'), style: { position: 'absolute', top: 88, left: 44 } }),
      ]),
      h('div', { key: 'ab', className: 'flex items-center gap-3' }, [
        h(Pad, { key: 'b', label: 'B', title: 'B', onClick: () => sendKey('x'), style: { background: 'rgba(248,113,113,0.16)', borderColor: 'rgba(248,113,113,0.45)', color: '#fca5a5' } }),
        h(Pad, { key: 'a', label: 'A', title: 'A', onClick: () => sendKey('z'), style: { background: 'rgba(74,222,128,0.16)', borderColor: 'rgba(74,222,128,0.45)', color: '#bbf7d0' } }),
      ]),
    ]),
    h('p', { key: 'note', className: 'mt-2 text-center font-mono', style: { fontSize: '0.52rem', color: 'var(--ui-text-tertiary)' } }, 'on-screen pad / A·B drive SNES; leaving this tab parks the live emulator'),
  ])
}

// ── TV & Games tab ───────────────────────────────────────────────────────────

function TvView({ ctx }) {
  // Use the shared TV store so the floating mini-player stays in sync.
  const tv = tvUse()
  const channels = activeChannels()
  const idx = tv.idx
  const powerOn = tv.powerOn
  const tvSize = tv.size
  const channel = channels[idx] || channels[0]
  const select = i => tvSetPersist({ idx: ((i % channels.length) + channels.length) % channels.length })

  // Pop the TV out as a floating, draggable card above the workspace. The shell
  // owns drag + position persistence. We capture the disposer so the X button
  // can unregister (close) it. Guard against double-register.
  const popOut = React.useCallback(() => {
    if (tvState.floating) return
    try {
      const prefs = loadPrefs()
      const size = prefs.popoutSize || 420
      const collapsed = !!prefs.popoutCollapsed
      const dispose = ctx.register({
        id: 'floating-tv',
        area: 'panes',
        title: 'TV',
        data: { placement: 'floating', anchor: 'bottom-right', width: String(size) + 'px', height: collapsed ? '44px' : 'min(78vh, 720px)' },
        render: () => h(FloatingTv, { ctx }),
      })
      floatingDispose = dispose
      tvSet({ floating: true, floatingCollapsed: collapsed })
      haptic('tap')
    } catch { /* already registered */ }
  }, [])

  // Keyboard shortcuts: arrows = channel, space = power, P = pop-out.
  useTvKeys(popOut)

  const closeFloating = React.useCallback(() => {
    try { floatingDispose && floatingDispose() } catch { /* ignore */ }
    floatingDispose = null
    tvSet({ floating: false })
  }, [])

  const [editing, setEditing] = React.useState(false)

  return h(ScrollArea, { className: 'h-full' },
    h('div', { className: 'px-6 py-6' }, [
      h('h1', {
        key: 'h1',
        className: 'mb-6 font-bold uppercase',
        style: { fontSize: '1.35rem', letterSpacing: '0.2em', color: 'var(--ui-text-primary)' } },
        'Entertainment'),
      h(TvCabinet, {
        key: 'tv',
        ctx,
        channel,
        channelIdx: idx,
        powerOn,
        size: tvSize,
        onPower: () => tvSetPersist({ powerOn: !tvState.powerOn }),
      }, h(ControlPanel, {
        key: 'ctrl',
        channelIdx: idx,
        powerOn,
        tvSize,
        onSize: v => tvSetPersist({ size: v }),
        onPopOut: popOut,
        onCloseFloating: closeFloating,
        onEditChannels: () => setEditing(true),
        onPower: () => tvSetPersist({ powerOn: !tvState.powerOn }),
        onPrev: () => select(idx - 1),
        onNext: () => select(idx + 1),
        onSelect: select,
      })),
      h('div', { key: 'g', className: 'mx-auto w-full', style: { maxWidth: tvSize } },
        h(TvGuide, { channelIdx: idx, onSelect: select })),
      h(GamesConsole, { key: 'gb', ctx }),
      editing ? h(EditChannels, { key: 'edit', onClose: () => setEditing(false) }) : null,
    ]),
  )
}

// Floating mini-player — a draggable card above the workspace. Reads the shared
// TV store so it mirrors the main pane's channel/power. Has its own X to close.
function FloatingTv({ ctx }) {
  const tv = tvUse()
  const channels = activeChannels()
  const idx = tv.idx
  const powerOn = tv.powerOn
  const ch = channels[idx] || channels[0]
  const gameMode = tv.floatingMode === 'game'
  const select = i => tvSet({ idx: ((i % channels.length) + channels.length) % channels.length })
  // Show the current Spotify track in the mini-player header while you code.
  const nowQ = useQuery({
    queryKey: [ID, 'floating', 'spotify', 'now'],
    queryFn: () => ctx.rest('/spotify/now-playing'),
    retry: false,
    refetchInterval: 10000,
  })
  const nowData = nowQ.data || {}
  const nowTrack = nowData.track || nowData.item || null
  const nowArtists = nowTrack ? (Array.isArray(nowTrack.artists) ? nowTrack.artists.map(a => (typeof a === 'string' ? a : a.name)) : []) : []
  const close = () => {
    try { floatingDispose && floatingDispose() } catch { /* ignore */ }
    floatingDispose = null
    tvSet({ floating: false })
  }
  const toggleMode = () => tvSet({ floatingMode: gameMode ? 'tv' : 'game' })
  const collapsed = tv.floatingCollapsed
  const toggleCollapse = () => tvSet({ floatingCollapsed: !collapsed })

  return h('div', {
    className: 'flex h-full flex-col',
    style: { background: 'rgba(8,8,12,0.98)', borderRadius: 12, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.08)' },
  }, [
    // custom close bar — the shell header above is the drag handle; we only
    // need an X to dismiss (the shell has no close, only a collapse chevron).
    h('div', {
      key: 'hdr',
      className: 'flex items-center justify-between gap-2 px-2 py-1',
      style: { borderBottom: '1px solid rgba(255,255,255,0.06)' },
    }, [
      h('div', { key: 'np', className: 'min-w-0 flex-1 truncate', style: { fontSize: '0.58rem', color: 'var(--ui-text-tertiary)', letterSpacing: '0.04em' } },
        nowTrack ? '♪ ' + nowTrack.name + (nowArtists.length ? ' — ' + nowArtists.join(', ') : '') : (gameMode ? 'GAME' : 'TV · ' + ch.name)),
      h('button', {
        key: 'mode', type: 'button', onClick: toggleMode, title: gameMode ? 'Switch to TV' : 'Switch to Game',
        className: 'rounded p-1 transition-colors',
        style: { color: 'var(--ui-text-tertiary)', fontSize: '0.65rem' },
        onPointerDown: e => e.stopPropagation(),
      }, gameMode ? '📺' : '🎮'),
      h('button', {
        key: 'collapse', type: 'button', onClick: toggleCollapse, title: collapsed ? 'Expand' : 'Collapse',
        className: 'rounded p-1 transition-colors',
        style: { color: 'var(--ui-text-tertiary)', fontSize: '0.7rem' },
        onPointerDown: e => e.stopPropagation(),
      }, collapsed ? '▢' : '—'),
      h('button', {
        key: 'x', type: 'button', onClick: close, title: 'Close mini-player',
        className: 'rounded p-1 transition-colors',
        style: { color: 'var(--ui-text-quaternary)', fontSize: '0.7rem' },
        onPointerDown: e => e.stopPropagation(),
      }, '✕'),
    ]),
    collapsed
      ? null
      : (gameMode
      ? h(GamesConsole, { key: 'game', ctx })
      : h(TvCabinet, {
        key: 'cab',
        ctx, channel: ch, channelIdx: idx, powerOn,
        size: tv.size,
        onPower: () => tvSet({ powerOn: !tvState.powerOn }),
      }, h('div', { key: 'ctl', className: 'px-3 pb-3' }, [
      h('div', { className: 'flex items-center justify-center gap-2' }, [
        h(RemoteButton, { key: 'p', icon: '⏻', title: 'Power', tone: powerOn ? 'power' : 'off', onClick: () => tvSet({ powerOn: !tvState.powerOn }) }),
        h(RemoteButton, { key: 'prev', icon: '⏮', title: 'Prev', onClick: () => select(idx - 1), disabled: !powerOn }),
        h(RemoteButton, { key: 'ch', icon: '📺', title: ch.name, tone: 'primary', wide: true, label: powerOn ? String(idx + 1).padStart(2, '0') : 'off', onClick: () => {}, disabled: !powerOn }),
        h(RemoteButton, { key: 'next', icon: '⏭', title: 'Next', onClick: () => select(idx + 1), disabled: !powerOn }),
      ]),
      // channel pills inside the mini-player for quick switching
      h('div', { key: 'pills', className: 'mt-2 flex flex-wrap items-center gap-1 overflow-x-auto', style: { scrollbarWidth: 'none' } },
        channels.map((c, i) => h('button', {
          key: c.id, type: 'button', title: c.name, onClick: () => select(i),
          className: 'flex-shrink-0 rounded-full border font-mono transition-transform active:scale-95',
          style: {
            height: 24, padding: '0 8px', fontSize: '0.5rem', fontWeight: 700,
            background: idx === i ? 'rgba(56,189,248,0.22)' : 'rgba(255,255,255,0.04)',
            borderColor: idx === i ? 'rgba(56,189,248,0.55)' : 'rgba(255,255,255,0.08)',
            color: idx === i ? '#e9d5ff' : 'rgba(255,255,255,0.4)',
          },
        }, String(i + 1).padStart(2, '0')))),
    ])))
  ])
}

// ── Discord ──────────────────────────────────────────────────────────────────

function DiscordView({ ctx }) {
  const [guildId, setGuildId] = React.useState(() => {
    try { return ctx.storage.get('discord-guild', null) } catch { return null }
  })
  const [channelId, setChannelId] = React.useState(() => {
    try { return ctx.storage.get('discord-channel', null) } catch { return null }
  })
  const [draft, setDraft] = React.useState('')

  const chooseGuild = (id) => { setGuildId(id); try { ctx.storage.set('discord-guild', id) } catch {} }
  const chooseChannel = (id) => { setChannelId(id); try { ctx.storage.set('discord-channel', id) } catch {} }

  const guildsQ = useQuery({
    queryKey: [ID, 'discord', 'guilds'],
    queryFn: () => ctx.rest('/discord/guilds'),
    retry: false,
  })
  const channelsQ = useQuery({
    queryKey: [ID, 'discord', 'channels', guildId],
    queryFn: () => ctx.rest(`/discord/channels?guild_id=${guildId}`),
    enabled: !!guildId,
    retry: false,
  })
  const msgsQ = useQuery({
    queryKey: [ID, 'discord', 'messages', channelId],
    queryFn: () => ctx.rest(`/discord/messages?channel_id=${channelId}&limit=40`),
    enabled: !!channelId,
    retry: false,
    refetchInterval: 15000,
  })

  if (guildsQ.isLoading) {
    return h('div', { className: 'flex h-full items-center justify-center' }, h(GlyphSpinner, {}))
  }
  if (guildsQ.error) {
    return h(ErrorState, {
      title: 'Discord unavailable',
      message: 'Add DISCORD_BOT_TOKEN to ~/.hermes/.env, give the bot Read Message History + Send Messages, then restart the dashboard.',
      onRetry: guildsQ.refetch,
    })
  }

  const list = guildsQ.data
  const guilds = Array.isArray(list) ? list : (list && list.guilds) || []
  const channels = Array.isArray(channelsQ.data) ? channelsQ.data : (channelsQ.data && channelsQ.data.channels) || []
  const messages = Array.isArray(msgsQ.data) ? msgsQ.data : (msgsQ.data && msgsQ.data.messages) || []

  const send = () => {
    const content = draft.trim()
    if (!content || !channelId) return
    setDraft('')
    ctx.rest('/discord/send', { method: 'POST', body: { channel_id: channelId, content } })
      .then(() => msgsQ.refetch())
      .catch(() => host.notifyError(new Error('Could not send message'), 'Discord'))
  }

  const pill = (active, label, onClick, key) => h('button', {
    key,
    type: 'button',
    onClick: () => { haptic('tap'); onClick() },
    className: 'flex-shrink-0 select-none rounded-full border px-3 py-1 transition-transform active:scale-95',
    style: {
      fontSize: '0.68rem',
      background: active ? 'rgba(56,189,248,0.18)' : 'rgba(255,255,255,0.04)',
      borderColor: active ? 'rgba(56,189,248,0.5)' : 'var(--ui-stroke-secondary)',
      color: active ? 'var(--ui-text-primary)' : 'var(--ui-text-tertiary)',
    },
  }, label)

  return h('div', { className: 'flex h-full flex-col' }, [
    h('div', {
      key: 'hd',
      className: 'border-b px-5 py-3 font-mono uppercase',
      style: { borderColor: 'var(--ui-stroke-secondary)', fontSize: '0.72rem', letterSpacing: '0.18em', color: 'var(--ui-text-secondary)' },
    }, 'Discord'),
    h('div', { key: 'sel', className: 'space-y-2 px-5 py-3' }, [
      h('div', { key: 'gl', className: 'flex flex-wrap gap-1.5' },
        guilds.map(g => pill(g.id === guildId, g.name, () => { chooseGuild(g.id); setChannelId(null) }, g.id))),
      guildId && channels.length
        ? h('div', { key: 'cl', className: 'flex flex-wrap gap-1.5' },
            channels.map(c => pill(c.id === channelId, '#' + c.name, () => chooseChannel(c.id), c.id)))
        : null,
    ]),
    h(ScrollArea, { key: 'msgs', className: 'flex-1' },
      h('div', { className: 'space-y-2 px-5 pb-4' },
        !channelId
          ? h(EmptyState, { title: 'Pick a channel', message: 'Choose a server, then a channel to read messages.' })
          : msgsQ.isLoading
            ? h('div', { className: 'flex justify-center py-6' }, h(GlyphSpinner, {}))
            : messages.slice().reverse().map(m =>
                h('div', { key: m.id, style: { fontSize: '0.75rem', lineHeight: 1.6 } }, [
                  h('span', { key: 'a', style: { fontWeight: 600, color: 'var(--ui-text-secondary)' } },
                    ((m.author && m.author.username) || 'unknown') + ': '),
                  h('span', { key: 'b', style: { color: 'var(--ui-text-primary)' } }, m.content || ''),
                ]),
              ),
      )),
    channelId ? h('div', {
      key: 'composer',
      className: 'flex items-center gap-2 border-t px-5 py-3',
      style: { borderColor: 'var(--ui-stroke-secondary)' },
    }, [
      h('input', {
        key: 'i',
        value: draft,
        placeholder: 'Message…',
        onChange: e => setDraft(e.target.value),
        onKeyDown: e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } },
        className: 'flex-1 rounded-md border bg-transparent px-3 py-2 outline-none',
        style: { fontSize: '0.78rem', borderColor: 'var(--ui-stroke-secondary)', color: 'var(--ui-text-primary)' },
      }),
      h(RemoteButton, { key: 's', label: 'send', title: 'Send', tone: 'primary', onClick: send }),
    ]) : null,
  ])
}

function FooterHero() {
  return h('div', {
    className: 'relative w-full overflow-hidden',
    style: { height: 200, marginTop: 12, borderRadius: 10 },
  }, [
    h('img', {
      key: 'img',
      src: FOOTER_HERO_URI,
      alt: 'Hermes entertainment hero',
      className: 'h-full w-full object-cover',
      style: { display: 'block' },
    }),
    h('div', {
      key: 'grad',
      className: 'absolute inset-0',
      style: { background: 'linear-gradient(180deg, rgba(0,0,0,0.20), rgba(0,0,242,0.18))' },
    }),
    h('div', {
      key: 'cap',
      className: 'absolute bottom-3 left-5 font-mono uppercase',
      style: { fontSize: '0.6rem', letterSpacing: '0.3em', color: 'rgba(245,245,245,0.9)' },
    }, 'Hermes · Entertainment'),
  ])
}

// ── Gallery ──────────────────────────────────────────────────────────────────

function GalleryTile({ ctx, file, onOpen }) {
  const [url, setUrl] = React.useState(null)
  const [failed, setFailed] = React.useState(false)

  React.useEffect(() => {
    let live = true
    // ?w=400 — thumbnails only. The full set is ~63 MB base64; pushing that
    // through the IPC bridge for a grid would stall the pane.
    fetchAsset(ctx, `/asset/gallery/${encodeURIComponent(file)}?w=400`)
      .then(u => live && setUrl(u))
      .catch(() => live && setFailed(true))
    return () => { live = false }
  }, [ctx, file])

  return h('button', {
    type: 'button',
    title: file,
    onClick: () => onOpen({ file }),
    className: 'overflow-hidden rounded-lg border transition-transform active:scale-95',
    style: { borderColor: 'var(--ui-stroke-secondary)', background: 'rgba(0,0,0,0.4)' },
  }, url
    ? h('img', { src: url, alt: file, loading: 'lazy', className: 'h-40 w-full object-cover' })
    : h('div', {
        className: 'flex h-40 items-center justify-center font-mono',
        style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)' },
      }, failed ? 'failed' : h(GlyphSpinner, {})))
}

/** Full-resolution view; fetched only when a tile is opened. */
function Lightbox({ ctx, file, onClose }) {
  const [url, setUrl] = React.useState(null)
  const [failed, setFailed] = React.useState(false)

  React.useEffect(() => {
    let live = true
    setUrl(null)
    setFailed(false)
    fetchAsset(ctx, `/asset/gallery/${encodeURIComponent(file)}`)
      .then(u => live && setUrl(u))
      .catch(() => live && setFailed(true))
    return () => { live = false }
  }, [ctx, file])

  React.useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose() }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  return h('div', {
    onClick: onClose,
    className: 'absolute inset-0 z-50 flex flex-col items-center justify-center gap-3 p-8',
    style: { background: 'rgba(0,0,0,0.88)', cursor: 'zoom-out' },
  }, [
    failed
      ? h('div', { key: 'e', className: 'font-mono', style: { fontSize: '0.7rem', color: '#fca5a5' } }, 'could not load image')
      : url
        ? h('img', { key: 'i', src: url, alt: file, style: { maxWidth: '100%', maxHeight: '82%', objectFit: 'contain', borderRadius: 8 } })
        : h(GlyphSpinner, { key: 's' }),
    h('div', { key: 'c', className: 'font-mono', style: { fontSize: '0.68rem', color: 'rgba(255,255,255,0.6)' } }, file),
  ])
}

function GalleryView({ ctx }) {
  const [lightbox, setLightbox] = React.useState(null)
  const listQ = useQuery({
    queryKey: [ID, 'gallery-list'],
    queryFn: () => ctx.rest('/gallery-list'),
    retry: false,
  })
  const [uploading, setUploading] = React.useState(false)
  const [upErr, setUpErr] = React.useState(null)

  const onUpload = (e) => {
    const file = e.target.files && e.target.files[0]
    e.target.value = ''  // allow re-selecting the same file
    if (!file) return
    setUploading(true)
    setUpErr(null)
    const reader = new FileReader()
    reader.onload = () => {
      const b64 = (reader.result || '').split(',')[1] || ''
      ctx.rest('/gallery/upload', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename: file.name, content: b64 }),
      })
        .then(() => listQ.refetch())
        .catch(err => setUpErr(String((err && err.message) || err)))
        .finally(() => setUploading(false))
    }
    reader.onerror = () => { setUpErr('Could not read file'); setUploading(false) }
    reader.readAsDataURL(file)
  }

  if (listQ.isLoading) return h('div', { className: 'flex h-full items-center justify-center' }, h(GlyphSpinner, {}))
  if (listQ.error) return h(ErrorState, { title: 'Gallery unavailable', message: 'The Entertainment backend is not reachable.', onRetry: listQ.refetch })

  const imgs = (listQ.data && listQ.data.images) || []
  if (!imgs.length) return h(EmptyState, { title: 'No gallery images', message: 'Add images to dashboard/public/gallery/' })

  return h('div', { className: 'relative flex h-full flex-col' }, [
    h('div', {
      key: 'hd',
      className: 'flex items-center justify-between border-b px-5 py-3 font-mono uppercase',
      style: { borderColor: 'var(--ui-stroke-secondary)', fontSize: '0.72rem', letterSpacing: '0.18em', color: 'var(--ui-text-secondary)' },
    }, [
      h('span', { key: 't' }, `Gallery · ${imgs.length}`),
      h('label', {
        key: 'up', title: 'Upload image', className: 'cursor-pointer rounded border px-2 py-1 transition-colors',
        style: { borderColor: 'var(--ui-stroke-secondary)', fontSize: '0.6rem', color: 'var(--ui-text-tertiary)' },
      }, uploading ? 'Uploading…' : '＋ Upload',
        h('input', { key: 'fi', type: 'file', accept: 'image/*', className: 'hidden', onChange: onUpload })),
    ]),
    upErr ? h('div', { key: 'err', className: 'px-5 pt-2 font-mono', style: { fontSize: '0.6rem', color: '#fca5a5' } }, upErr) : null,
    h(ScrollArea, { key: 'grid', className: 'flex-1' },
      h('div', {
        className: 'flex flex-col gap-3 p-5',
      }, [
        h('div', {
          key: 'tiles',
          className: 'grid gap-3',
          style: { gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))' },
        }, imgs.map(f => h(GalleryTile, { key: f, ctx, file: f, onOpen: setLightbox }))),
        h(FooterHero, { key: 'hero' }),
      ])),
    lightbox ? h(Lightbox, { key: 'lb', ctx, file: lightbox.file, onClose: () => setLightbox(null) }) : null,
  ])
}

// ── Music (multi-provider: Spotify + Apple Music) ─────────────────────────────

function MusicView({ ctx }) {
  const [provider, setProvider] = React.useState('spotify')

  // Spotify
  const spotNow = useQuery({
    queryKey: [ID, 'spotify', 'now'],
    queryFn: () => ctx.rest('/spotify/now-playing'),
    retry: false,
    refetchInterval: provider === 'spotify' ? 10000 : false,
  })
  const spotRecent = useQuery({
    queryKey: [ID, 'spotify', 'recent'],
    queryFn: () => ctx.rest('/spotify/recently-played'),
    retry: false,
  })
  const spotDevices = useQuery({
    queryKey: [ID, 'spotify', 'devices'],
    queryFn: () => ctx.rest('/spotify/devices'),
    retry: false,
    refetchInterval: 20000,
    enabled: provider === 'spotify',
  })

  // Apple Music
  const appleStatus = useQuery({
    queryKey: [ID, 'apple', 'status'],
    queryFn: () => ctx.rest('/apple/status'),
    retry: false,
    enabled: provider === 'apple',
  })
  const appleRecent = useQuery({
    queryKey: [ID, 'apple', 'recent'],
    queryFn: () => ctx.rest('/apple/recently-played'),
    retry: false,
    enabled: provider === 'apple',
  })

  const ProviderTabs = h('div', {
    key: 'prov',
    className: 'mb-6 flex items-center gap-1 rounded-lg p-1',
    style: { background: 'rgba(255,255,255,0.04)', border: '1px solid var(--ui-stroke-secondary)' },
  }, [
    h('button', {
      key: 'sp', type: 'button', onClick: () => setProvider('spotify'),
      className: 'flex-1 rounded-md px-3 py-1.5 font-mono uppercase transition-colors',
      style: { fontSize: '0.62rem', letterSpacing: '0.12em', background: provider === 'spotify' ? 'rgba(29,185,84,0.18)' : 'transparent', color: provider === 'spotify' ? '#1db954' : 'var(--ui-text-tertiary)' },
    }, 'Spotify'),
    h('button', {
      key: 'ap', type: 'button', onClick: () => setProvider('apple'),
      className: 'flex-1 rounded-md px-3 py-1.5 font-mono uppercase transition-colors',
      style: { fontSize: '0.62rem', letterSpacing: '0.12em', background: provider === 'apple' ? 'rgba(253,53,80,0.18)' : 'transparent', color: provider === 'apple' ? '#fb3b5c' : 'var(--ui-text-tertiary)' },
    }, 'Apple Music'),
  ])

  if (provider === 'apple') {
    if (appleStatus.isLoading) return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [ProviderTabs, h('div', { className: 'flex h-40 items-center justify-center' }, h(GlyphSpinner, {}))]))
    if (appleStatus.data && !appleStatus.data.connected) {
      return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [
        ProviderTabs,
        h(ErrorState, {
          title: 'Apple Music not connected',
          message: 'Set APPLE_MUSIC_DEVELOPER_TOKEN in the dashboard env to show your recently played. Tap a track to open it in the Music app.',
          onRetry: appleStatus.refetch,
        }),
      ]))
    }
    const recent = (appleRecent.data) || []
    return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [
      ProviderTabs,
      h('div', { key: 'hd', className: 'mb-4 font-mono uppercase', style: { fontSize: '0.72rem', letterSpacing: '0.18em', color: 'var(--ui-text-secondary)' } }, 'Apple Music · Recently Played'),
      recent.length ? h('div', { key: 'rl', className: 'space-y-1.5' }, recent.slice(0, 20).map((t, i) =>
        h('button', {
          key: (t.id || '') + i, type: 'button', onClick: () => { if (t.url) window.open(t.url, '_blank'); },
          className: 'flex w-full items-center gap-3 rounded-md px-3 py-2 text-left transition-colors',
          style: { background: 'rgba(255,255,255,0.03)' },
        }, [
          h('div', { key: 'art', className: 'h-10 w-10 flex-shrink-0 overflow-hidden rounded', style: { background: 'rgba(0,0,0,0.4)' } },
            t.image ? h('img', { src: t.image, alt: '', className: 'h-full w-full object-cover' }) : null),
          h('div', { key: 'meta', className: 'min-w-0' }, [
            h('div', { key: 'n', style: { fontSize: '0.8rem', color: 'var(--ui-text-primary)' }, className: 'truncate' }, t.name || 'unknown'),
            h('div', { key: 'a', style: { fontSize: '0.7rem', color: 'var(--ui-text-tertiary)' }, className: 'truncate' }, (t.artists || []).join(', ')),
          ]),
        ]),
      )) : h('div', { key: 'empty', className: 'font-mono', style: { fontSize: '0.65rem', letterSpacing: '0.1em', color: 'var(--ui-text-tertiary)' } }, 'No recently played yet — tap a song in the Music app, then reload.'),
    ]))
  }

  // Spotify (default)
  if (spotNow.isLoading) return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [ProviderTabs, h('div', { className: 'flex h-40 items-center justify-center' }, h(GlyphSpinner, {}))]))
  if (spotNow.error) {
    return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [
      ProviderTabs,
      h(ErrorState, { title: 'Spotify not connected', message: 'Run `hermes auth spotify`, then retry.', onRetry: spotNow.refetch }),
    ]))
  }

  const now = spotNow.data || {}
  const track = now.track || null
  const playing = !!now.playing
  const artists = track ? (Array.isArray(track.artists) ? track.artists.map(a => (typeof a === 'string' ? a : a.name)) : []) : []
  const cover = track && (track.image || track.album_art || (track.album && track.album.image)) || null
  const recent = (spotRecent.data && (spotRecent.data.items || spotRecent.data.tracks)) || []
  const progressMs = now.progress_ms || 0
  const durationMs = (track && track.duration_ms) || 0
  const shuffle = now.shuffle_state
  const repeat = now.repeat_state || 'off'

  // Live progress ticker (only while playing)
  const [tick, setTick] = React.useState(0)
  const [volume, setVolume] = React.useState(() => {
    try { const p = PLUGIN_STORAGE.get('prefs', null); if (p && p.volume != null) return p.volume } catch {}
    return 70
  })
  React.useEffect(() => {
    if (!playing) return
    const id = setInterval(() => setTick(t => t + 1), 1000)
    return () => clearInterval(id)
  }, [playing])
  const shownProgress = playing ? Math.min(progressMs + tick * 1000, durationMs || progressMs + tick * 1000) : progressMs

  const fire = (path, body) => () => {
    haptic('tap')
    ctx.rest(path, { method: 'POST', body: body ? JSON.stringify(body) : undefined })
      .then(() => spotNow.refetch())
      .catch(() => host.notifyError(new Error('Spotify action failed'), 'Music'))
  }
  const cycleRepeat = () => {
    const order = ['off', 'context', 'track']
    const nextState = order[(order.indexOf(repeat) + 1) % order.length]
    fire('/spotify/repeat', { state: nextState })()
  }
  const fmt = ms => {
    if (!ms || ms < 0) return '0:00'
    const s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0')
  }

  return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [
    ProviderTabs,
    h('div', { key: 'hd', className: 'mb-6 font-mono uppercase', style: { fontSize: '0.72rem', letterSpacing: '0.18em', color: 'var(--ui-text-secondary)' } }, 'Mixtape'),
    h('div', { key: 'np', className: 'flex flex-col items-center gap-4' }, [
      h('div', { key: 'art', className: 'overflow-hidden rounded-xl border', style: { width: 220, height: 220, borderColor: 'var(--ui-stroke-secondary)', background: 'rgba(0,0,0,0.4)' } },
        cover ? h('img', { src: cover, alt: 'cover', className: 'h-full w-full object-cover' })
          : h('div', { className: 'flex h-full w-full items-center justify-center font-mono', style: { fontSize: '0.6rem', letterSpacing: '0.3em', color: 'var(--ui-text-tertiary)' } }, 'NO ART')),
      h('div', { key: 'meta', className: 'text-center' }, [
        h('div', { key: 'n', style: { fontSize: '0.95rem', fontWeight: 600, color: 'var(--ui-text-primary)' } }, track ? track.name : 'Nothing playing'),
        h('div', { key: 'a', style: { fontSize: '0.75rem', color: 'var(--ui-text-tertiary)' } }, artists.length ? artists.join(', ') : '—'),
        now.device ? h('div', { key: 'd', style: { fontSize: '0.55rem', color: 'var(--ui-text-quaternary)', marginTop: 4 } }, '▣ ' + now.device) : null,
      ]),
      // progress bar (click to seek)
      h('div', { key: 'prog', className: 'w-full', style: { maxWidth: 320 } }, [
        h('div', {
          key: 'bar', className: 'cursor-pointer overflow-hidden rounded-full', style: { height: 4, background: 'rgba(255,255,255,0.1)' },
          onClick: (e) => {
            if (!durationMs) return
            const rect = e.currentTarget.getBoundingClientRect()
            const pct = (e.clientX - rect.left) / rect.width
            const pos = Math.max(0, Math.min(1, pct)) * durationMs
            fire('/spotify/seek', { position_ms: Math.round(pos) })()
          },
        },
          h('div', { key: 'fill', style: { height: '100%', width: (durationMs ? (shownProgress / durationMs) * 100 : 0) + '%', background: '#1db954', transition: 'width 0.9s linear' } })),
        h('div', { key: 'times', className: 'mt-1 flex justify-between font-mono', style: { fontSize: '0.5rem', color: 'var(--ui-text-tertiary)' } }, [
          h('span', { key: 'p' }, fmt(shownProgress)),
          h('span', { key: 'd' }, fmt(durationMs)),
        ]),
      ]),
      // transport row 1: shuffle / prev / play-pause / next / repeat
      h('div', { key: 'ctl', className: 'flex items-center gap-2' }, [
        h(RemoteButton, { key: 'sh', label: '🔀', title: 'Shuffle', tone: shuffle ? 'primary' : 'off', onClick: fire('/spotify/shuffle', { state: !shuffle }) }),
        h(RemoteButton, { key: 'p', label: '◀◀', title: 'Previous', onClick: fire('/spotify/previous') }),
        h(RemoteButton, { key: 'x', label: playing ? 'pause' : 'play', title: 'Play/Pause', tone: 'primary', wide: true, onClick: fire(playing ? '/spotify/pause' : '/spotify/play') }),
        h(RemoteButton, { key: 'n', label: '▶▶', title: 'Next', onClick: fire('/spotify/next') }),
        h(RemoteButton, { key: 'rp', label: repeat === 'off' ? '↻' : repeat === 'track' ? '🔂' : '🔁', title: 'Repeat (' + repeat + ')', tone: repeat !== 'off' ? 'primary' : 'off', onClick: cycleRepeat }),
      ]),
      // volume slider
      h('div', { key: 'vol', className: 'flex items-center gap-2', style: { maxWidth: 320 } }, [
        h('span', { key: 'ic', style: { fontSize: '0.7rem', color: 'var(--ui-text-tertiary)' } }, '🔊'),
        h('input', {
          key: 'v', type: 'range', min: 0, max: 100, step: 1, value: volume,
          onChange: e => { const v = parseInt(e.target.value, 10); setVolume(v); fire('/spotify/volume', { volume: v })() },
          className: 'flex-1', style: { accentColor: '#1db954', height: 4 },
        }),
        h('span', { key: 'vv', className: 'font-mono', style: { fontSize: '0.5rem', color: 'var(--ui-text-tertiary)', width: 24, textAlign: 'right' } }, String(volume)),
      ]),
      // device picker
      (() => {
        const devs = (spotDevices.data && spotDevices.data.devices) || []
        if (!devs.length) return null
        const active = devs.find(d => d.is_active) || null
        return h('div', { key: 'dev', className: 'flex items-center gap-2', style: { maxWidth: 320 } }, [
          h('span', { key: 'ic', style: { fontSize: '0.7rem' }, title: 'Playback device' }, '📡'),
          h('select', {
            key: 'sel',
            value: active ? active.id : '',
            onChange: e => {
              const id = e.target.value
              if (!id) return
              haptic('tap')
              ctx.rest('/spotify/transfer', { method: 'POST', body: JSON.stringify({ device_id: id }) })
                .then(() => spotDevices.refetch())
                .catch(() => host.notifyError(new Error('Could not switch device'), 'Music'))
            },
            className: 'flex-1 rounded border bg-transparent px-2 py-1',
            style: { fontSize: '0.62rem', color: 'var(--ui-text-primary)', borderColor: 'var(--ui-stroke-secondary)' },
          }, devs.map(d => h('option', { key: d.id || d.name, value: d.id || '', style: { color: '#000' } }, (d.is_active ? '▣ ' : '') + d.name))),
        ])
      })(),
    ]),
    recent.length ? h('div', { key: 'recent', className: 'mt-8' }, [
      h('div', { key: 'rh', className: 'mb-3 font-mono uppercase', style: { fontSize: '0.62rem', letterSpacing: '0.3em', color: 'var(--ui-text-tertiary)' } }, 'B-side · recently played'),
      h('div', { key: 'rl', className: 'space-y-1.5' }, recent.slice(0, 12).map((it, i) => {
        const t = it.track || it
        const as = Array.isArray(t.artists) ? t.artists.map(a => (typeof a === 'string' ? a : a.name)) : []
        const uri = t.uri || (t.external_urls && t.external_urls.spotify)
        return h('button', {
          key: (t.id || '') + i, type: 'button',
          onClick: () => { if (t.external_urls && t.external_urls.spotify) window.open(t.external_urls.spotify, '_blank'); else if (uri) ctx.rest('/spotify/play', { method: 'POST', body: JSON.stringify({ uri }) }).catch(() => {}) },
          className: 'flex w-full items-baseline gap-3 rounded-md px-3 py-2 text-left transition-colors hover:bg-white/5',
          style: { background: 'rgba(255,255,255,0.03)' },
        }, [
          h('span', { key: 'i', className: 'font-mono', style: { fontSize: '0.6rem', color: 'var(--ui-text-tertiary)' } }, String(i + 1).padStart(2, '0')),
          h('span', { key: 'n', style: { fontSize: '0.78rem', color: 'var(--ui-text-primary)' } }, t.name || 'unknown'),
          h('span', { key: 'a', style: { fontSize: '0.7rem', color: 'var(--ui-text-tertiary)' } }, as.join(', ')),
        ])
      })),
    ]) : null,
  ]))
}

// ── Preferences ──────────────────────────────────────────────────────────────
// Persists user defaults so the TV/music/pop-out open the way you like.

function loadPrefs() {
  try {
    const p = PLUGIN_STORAGE.get('prefs', null)
    return p && typeof p === 'object' ? p : {}
  } catch { return {} }
}
function savePrefs(patch) {
  const next = Object.assign(loadPrefs(), patch)
  try { PLUGIN_STORAGE.set('prefs', next) } catch {}
  return next
}

function PrefsRow({ label, hint, children }) {
  return h('div', { className: 'flex items-center justify-between gap-4 border-b py-3', style: { borderColor: 'var(--ui-stroke-secondary)' } }, [
    h('div', { key: 'l' }, [
      h('div', { key: 'lab', style: { fontSize: '0.78rem', color: 'var(--ui-text-primary)' } }, label),
      hint ? h('div', { key: 'h', style: { fontSize: '0.6rem', color: 'var(--ui-text-tertiary)' } }, hint) : null,
    ]),
    h('div', { key: 'c' }, children),
  ])
}

function PrefsView({ ctx }) {
  const [prefs, setPrefs] = React.useState(() => loadPrefs())
  const update = (patch) => setPrefs(savePrefs(patch))

  return h(ScrollArea, { className: 'h-full' }, h('div', { className: 'px-6 py-6' }, [
    h('div', { key: 'hd', className: 'mb-4 font-mono uppercase', style: { fontSize: '0.72rem', letterSpacing: '0.18em', color: 'var(--ui-text-secondary)' } }, 'Preferences'),

    h(PrefsRow, {
      key: 'r1', label: 'Default tab', hint: 'Which tab opens when you open Entertainment.',
      children: h('select', {
        key: 's', value: prefs.defaultTab || 'tv',
        onChange: e => update({ defaultTab: e.target.value }),
        className: 'rounded border bg-transparent px-2 py-1',
        style: { fontSize: '0.62rem', color: 'var(--ui-text-primary)', borderColor: 'var(--ui-stroke-secondary)' },
      }, TABS.map(t => h('option', { key: t.id, value: t.id, style: { color: '#000' } }, t.label))),
    }),

    h(PrefsRow, {
      key: 'r2', label: 'Pop-out size', hint: 'Width of the floating mini-player (px).',
      children: h('div', { key: 'w', className: 'flex items-center gap-2' }, [
        h('input', {
          key: 'i', type: 'range', min: 280, max: 720, step: 10, value: prefs.popoutSize || 420,
          onChange: e => update({ popoutSize: parseInt(e.target.value, 10) }),
          style: { accentColor: '#38bdf8', height: 4 },
        }),
        h('span', { key: 'v', className: 'font-mono', style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)', width: 32, textAlign: 'right' } }, String(prefs.popoutSize || 420)),
      ]),
    }),

    h(PrefsRow, {
      key: 'r3', label: 'Pop-out starts collapsed', hint: 'Open the mini-player as a slim title bar.',
      children: h('input', {
        key: 'c', type: 'checkbox', checked: !!prefs.popoutCollapsed,
        onChange: e => update({ popoutCollapsed: e.target.checked }),
        style: { accentColor: '#38bdf8', width: 16, height: 16 },
      }),
    }),

    h(PrefsRow, {
      key: 'r4', label: 'Default volume', hint: 'Spotify volume applied to the music player.',
      children: h('div', { key: 'w', className: 'flex items-center gap-2' }, [
        h('input', {
          key: 'i', type: 'range', min: 0, max: 100, step: 1, value: prefs.volume != null ? prefs.volume : 70,
          onChange: e => update({ volume: parseInt(e.target.value, 10) }),
          style: { accentColor: '#1db954', height: 4 },
        }),
        h('span', { key: 'v', className: 'font-mono', style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)', width: 28, textAlign: 'right' } }, String(prefs.volume != null ? prefs.volume : 70)),
      ]),
    }),

    h('div', { key: 'reset', className: 'mt-6' }, [
      h('button', {
        key: 'b', type: 'button', onClick: () => { try { PLUGIN_STORAGE.set('prefs', {}) } catch {}; setPrefs({}) },
        className: 'rounded border px-3 py-1.5 transition-colors',
        style: { fontSize: '0.62rem', color: 'var(--ui-text-tertiary)', borderColor: 'var(--ui-stroke-secondary)' },
      }, 'Reset to defaults'),
      h('div', { key: 'note', className: 'mt-2 font-mono', style: { fontSize: '0.55rem', color: 'var(--ui-text-tertiary)' } }, 'Tab + pop-out state also persist automatically as you use them.'),
    ]),
  ]))
}

// ── Shell ────────────────────────────────────────────────────────────────────

const TABS = [
  { id: 'tv', label: 'TV & Games', render: (ctx) => h(TvView, { ctx }) },
  { id: 'discord', label: 'Discord', render: (ctx) => h(DiscordView, { ctx }) },
  { id: 'gallery', label: 'Gallery', render: (ctx) => h(GalleryView, { ctx }) },
  { id: 'music', label: 'Music', render: (ctx) => h(MusicView, { ctx }) },
  { id: 'prefs', label: 'Prefs', render: (ctx) => h(PrefsView, { ctx }) },
]

function EntertainmentPane({ ctx }) {
  const [tab, setTabState] = React.useState(() => {
    try {
      const last = ctx.storage.get('active-tab', null)
      if (last) return last
      const p = ctx.storage.get('prefs', null)
      if (p && p.defaultTab) return p.defaultTab
    } catch {}
    return 'tv'
  })
  const setTab = (id) => { setTabState(id); try { ctx.storage.set('active-tab', id) } catch {} }
  const active = TABS.find(t => t.id === tab) || TABS[0]

  return h('div', { className: 'flex h-full flex-col' }, [
    h('div', {
      key: 'tabs',
      className: 'flex flex-shrink-0 items-center gap-1 border-b px-3 py-2',
      style: { borderColor: 'var(--ui-stroke-secondary)' },
    }, TABS.map(t =>
      h('button', {
        key: t.id,
        type: 'button',
        onClick: () => { haptic('tap'); setTab(t.id) },
        className: 'select-none rounded-md px-3 py-1.5 font-mono uppercase transition-colors',
        style: {
          fontSize: '0.65rem',
          letterSpacing: '0.12em',
          background: tab === t.id ? 'rgba(56,189,248,0.16)' : 'transparent',
          color: tab === t.id ? 'var(--ui-text-primary)' : 'var(--ui-text-tertiary)',
        },
      }, t.label),
    )),
    h('div', { key: 'body', className: 'min-h-0 flex-1 overflow-hidden' }, active.render(ctx)),
  ])
}

export default {
  // MUST equal the dashboard manifest name — ctx.rest is scoped to
  // /api/plugins/<id>/ and the backend mounts under this exact string.
  id: ID,
  name: 'Entertainment Pack',
  register(ctx) {
    // Capture storage so TV prefs persist across reloads.
    PLUGIN_STORAGE = ctx.storage
    tvLoad()
    channelsLoad()
    // Reset transient floating-pane state on every (re)load so a stale pop-out
    // from a previous session can't be re-adopted. The X button's disposer fully
    // unregisters it; this guards against the shell restoring it from layout.
    tvState.floating = false
    tvState.floatingCollapsed = false
    floatingDispose = null
    // Inject the TV cross-fade keyframes once.
    if (typeof document !== 'undefined' && !document.getElementById('hermes-tv-fade')) {
      const s = document.createElement('style')
      s.id = 'hermes-tv-fade'
      s.textContent = '@keyframes hermesTvFade{from{opacity:0}to{opacity:1}}'
      document.head.appendChild(s)
    }
    // Relocate Entertainment from a full-width main pane to the sidebar, placed
    // directly beneath Social. Social registers its nav row at order: 60; we use
    // 61 so the Entertainment row nests right below it. The sidebar nav row pairs
    // with a route page at /entertainment (the same registry built-ins use, so
    // 'sidebar.nav' / 'routes' work here exactly as for Social/Kanban). We DROP
    // the old 'panes' main pane so EntertainmentPane isn't mounted twice — the
    // route page is a separate React tree. Tradeoff: like Social, it becomes a
    // navigable page (unmounts on leave); logins persist, scroll state does not.
    // The app uses a HashRouter, so navigation sets window.location.hash.
    const navEntertainment = () => { try { window.location.hash = '#/entertainment' } catch { /* noop */ } }
    ctx.register({ id: 'nav', area: 'sidebar.nav', order: 61,
      data: { codicon: 'device-desktop', label: 'Entertainment', path: '/entertainment' } })
    ctx.register({ id: 'route', area: 'routes',
      data: { path: '/entertainment' },
      render: () => h(EntertainmentPane, { ctx }) })
    // ⌘K "Open Entertainment" — click-to-run native palette row.
    ctx.register({ id: 'palette.open', area: 'palette',
      data: { id: 'entertainment.open', label: 'Open Entertainment',
              keywords: ['entertainment', 'tv', 'games', 'gallery', 'music'], run: navEntertainment } })
    // Global hotkey ⌘⇧E — first-class contributed keybind (rebindable).
    ctx.register({ id: 'key.open', area: 'keybinds',
      data: { id: 'entertainment.openHotkey', category: 'view',
              defaults: ['mod+shift+e'], label: 'Entertainment: Open', run: navEntertainment } })
  },
}

// Test-only export for the offline verification harness (Path C). The app ignores
// this bare assignment; it is not part of the plugin's public surface.
globalThis.__TEST__ = { GalleryView, GalleryTile, FooterHero, FOOTER_HERO_URI }






